/* Structured response contract. All current results explicitly identify the mock adapter. */
window.AnalysisCards=(()=>{
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function create(media,sourceId,subject={}){return {...subject,kind:media.kind,sourceId,createdAt:Date.now(),status:'insufficient',mode:'demo',name:media.name,duration:media.duration||null,bytes:media.blob?.size||0,observations:media.observations||[],replies:[]};}
const section=(glyph,title,body)=>`<section class="analysis-section"><h4>${icon(glyph)}${title}</h4><p>${body}</p></section>`;
function render(m,input=''){const a=m.analysis,photo=a.kind==='image';let content='';
if(photo){content=section('diaper','便便状态','暂时无法判断')+`<section class="analysis-section"><h4>${icon('search')}便便特征</h4><div class="stool-features">${[['water','颜色'],['diaper','形态'],['alert','特殊特征']].map(([i,t])=>`<div>${icon(i)}<span>${t}</span><strong>尚未识别</strong></div>`).join('')}</div></section>`+section('journal','结果解读','已收到图片，但分析服务尚未连接，目前没有可用的识别结果。')+section('edit','行动建议','可以补充你看到的颜色、形态和发生时间，作为这次观察的备注。')+section('alert','需要关注的情况','尚未生成针对这次观察的关注项，不能据此确认宝宝是否健康。');}
else content=section('search','可能原因','信息不足，暂时无法判断')+section('waveform','判断依据',`${a.duration?'收到 '+Math.round(a.duration)+' 秒录音。':'已收到录音文件。'}声音识别服务尚未连接，没有有效的哭声分析结果。`)+section('heart','安抚建议','暂不生成针对性建议。可以补充哭闹前后发生的事，先把观察整理完整。');
const notes=(a.observations||[]).length?`<section class="analysis-notes"><h4>${icon('user')}你补充的观察</h4>${a.observations.map(n=>`<p>${escape(n)}</p>`).join('')}<small>以上来自你的描述，尚未经识别或核实。</small></section>`:'';
return `<div class="structured-analysis" data-analysis-kind="${a.kind}" data-card-id="${escape(m.id)}"><header><span class="analysis-card-icon">${icon(photo?'camera':'waveform')}</span><div><h3>${photo?'这次便便观察':'这段哭声观察'}</h3><small>${new Date(a.createdAt).toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit',hour12:false})} · ${escape(a.babyName||'')} · ${escape(a.name)}</small></div></header><div class="analysis-status">${icon('search')}信息不足<span class="mode-tag">模拟分析</span></div>${content}${notes}<div class="analysis-actions"><button type="button" class="quiet" data-action="analysis-source" data-id="${escape(a.sourceId)}">${icon(photo?'camera':'waveform')}查看这次材料</button><button type="button" class="quiet" data-action="analysis-question" data-id="${escape(m.id)}">${icon('message')}如何理解这次结果</button></div><details class="analysis-compose" ${input?'open':''}><summary>${icon('edit')}补充观察或提问${icon('chevron-down')}</summary><form class="analysis-reply-form" data-card="${escape(m.id)}"><label class="sr-only" for="reply-${escape(m.id)}">补充观察或提问</label><textarea id="reply-${escape(m.id)}" name="observation" rows="2" maxlength="600" placeholder="${photo?'比如：看到的颜色、形态，是什么时候…':'比如：刚喂过奶，哭声持续了多久…'}">${escape(input)}</textarea><p class="analysis-inline-error" role="alert" hidden></p><button type="submit" class="primary">发送补充 ${icon('arrow-up')}</button><small>补充内容会保留在本次观察里，不会自动生成健康结论。</small></form></details></div>`;
}
function reply(text){return /[？?]|怎么|如何|为什么|说明|需要什么/.test(text)?{observation:false,text:'这张卡目前表示信息不足，没有识别出原因或健康状态。你可以补充当时观察到的情况；真实分析服务接入后，才能生成有依据的解读。'}:{observation:true,text:'已把你的描述补充到这次观察卡。补充内容尚未经识别或核实，目前仍不能据此判断哭闹原因或便便状态。'};}
return {create,render,reply};
})();
